---INVOICE---
'use strict';

const { billableWeightKg } = require('./weight');
const { tierFor, basePriceUsd, shippingUsd } = require('./pricing');
const { roundCurrency } = require('./format');
const { applyDiscount } = require('./discount');

// Tax is charged on the parcel subtotal only; shipping is never taxed.
const TAX_RATE = 0.07;

// buildInvoice(order) -> {
//   id,
//   lines: [{ description, quantity, billableKg, tier, amountUsd }],
//   shippingZone, shippingUsd,
//   subtotalUsd, discount, taxUsd, totalUsd
// }
//
// `discount` is null when order.discountCode is absent, otherwise
// { code, amountUsd } for the applied discount (see lib/discount.js).
//
// order = {
//   id: string,
//   zone: 'domestic' | 'regional' | 'international',
//   items: [{ description, quantity?, weightKg, dimensionsCm: { length, width, height } }],
//   discountCode?: string
// }
function buildInvoice(order) {
  if (!order || typeof order !== 'object') {
    throw new TypeError('buildInvoice requires an order object');
  }
  if (typeof order.id !== 'string' || order.id === '') {
    throw new TypeError('order.id must be a non-empty string');
  }
  if (!Array.isArray(order.items) || order.items.length === 0) {
    throw new TypeError('order.items must be a non-empty array');
  }

  const lines = [];
  let subtotal = 0;
  for (const item of order.items) {
    const quantity = item.quantity === undefined ? 1 : item.quantity;
    if (!Number.isInteger(quantity) || quantity <= 0) {
      throw new TypeError('item.quantity must be a positive integer');
    }
    const kg = billableWeightKg(item.weightKg, item.dimensionsCm);
    const amountUsd = roundCurrency(quantity * basePriceUsd(kg));
    lines.push({
      description: item.description,
      quantity,
      billableKg: kg,
      tier: tierFor(kg),
      amountUsd,
    });
    subtotal += amountUsd;
  }

  const subtotalUsd = roundCurrency(subtotal);
  let shipUsd = shippingUsd(order.zone);

  let discount = null;
  let taxUsd;
  let totalUsd;

  if (order.discountCode !== undefined) {
    const result = applyDiscount(order.discountCode, {
      subtotalUsd,
      shippingUsd: shipUsd,
      taxRate: TAX_RATE,
    });
    discount = { code: result.code, amountUsd: result.amountUsd };
    shipUsd = result.shippingUsd;
    taxUsd = result.taxUsd;
    totalUsd = result.totalUsd;
  } else {
    taxUsd = roundCurrency(TAX_RATE * subtotalUsd);
    totalUsd = roundCurrency(subtotalUsd + shipUsd + taxUsd);
  }

  return {
    id: order.id,
    lines,
    shippingZone: order.zone,
    shippingUsd: shipUsd,
    subtotalUsd,
    discount,
    taxUsd,
    totalUsd,
  };
}

module.exports = { buildInvoice, TAX_RATE };
---FORMAT---
'use strict';

// Currency helpers. THE PROJECT'S ROUNDING POLICY LIVES HERE AND ONLY HERE:
// every monetary amount is rounded half-up to 2 decimal places via
// roundCurrency, and printed via money. Nothing else in the project may
// re-implement rounding.

function roundCurrency(value) {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError('roundCurrency requires a finite number');
  }
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function money(value) {
  return roundCurrency(value).toFixed(2);
}

module.exports = { roundCurrency, money };
---DISCOUNT---
'use strict';

// Discount codes: the code table and the amount-computation logic live here,
// and only here. lib/invoice.js and bin/cli.js consume this module; neither
// re-implements a discount rule or re-implements rounding. All rounding goes
// through lib/format.js's roundCurrency, per the project's rounding policy.

const { roundCurrency } = require('./format');

const CODES = new Set(['SAVE10', 'FREESHIP']);

class UnknownDiscountCodeError extends Error {
  constructor(code) {
    super('unknown discount code: ' + code);
    this.name = 'UnknownDiscountCodeError';
    this.code = code;
  }
}

// applyDiscount(code, { subtotalUsd, shippingUsd, taxRate }) -> {
//   code, amountUsd, shippingUsd, taxUsd, totalUsd
// }
//
// subtotalUsd and shippingUsd are the order's pre-discount subtotal and
// shipping charge; taxRate is the project's tax rate (see lib/invoice.js).
// Returns the discount amount shown on the invoice plus the (possibly
// adjusted) shipping/tax/total figures. Throws UnknownDiscountCodeError if
// `code` is not exactly one of the recognized codes.
function applyDiscount(code, { subtotalUsd, shippingUsd, taxRate }) {
  if (!CODES.has(code)) {
    throw new UnknownDiscountCodeError(code);
  }

  if (code === 'SAVE10') {
    const amountUsd = Math.min(roundCurrency(0.1 * subtotalUsd), 50);
    const taxableUsd = roundCurrency(subtotalUsd - amountUsd);
    const taxUsd = roundCurrency(taxRate * taxableUsd);
    const totalUsd = roundCurrency(taxableUsd + shippingUsd + taxUsd);
    return { code, amountUsd, shippingUsd, taxUsd, totalUsd };
  }

  // FREESHIP: shipping is zeroed; the discount amount shown is the zone's
  // normal shipping price. Subtotal and tax are unaffected.
  const amountUsd = shippingUsd;
  const taxUsd = roundCurrency(taxRate * subtotalUsd);
  const totalUsd = roundCurrency(subtotalUsd + taxUsd);
  return { code, amountUsd, shippingUsd: 0, taxUsd, totalUsd };
}

module.exports = { applyDiscount, UnknownDiscountCodeError };

