'use strict';

const path = require('path');
const { execFileSync } = require('child_process');

module.exports = function ({ assertEqual }) {
  const cli = path.join(__dirname, '..', 'bin', 'cli.js');
  const fixture = path.join(__dirname, 'fixtures', 'order-a.json');

  const out = execFileSync('node', [cli, fixture], { encoding: 'utf8' });
  const expected = [
    'INVOICE ORD-A',
    'ITEM Books qty=1 billable_kg=2.00 tier=small amount=8.00',
    'ITEM Monitor qty=1 billable_kg=10.80 tier=medium amount=15.00',
    'SHIPPING zone=domestic amount=4.50',
    'SUBTOTAL 23.00',
    'TAX 1.61',
    'TOTAL 29.11',
    '',
  ].join('\n');
  // Regression: an order with no discountCode must be byte-identical to
  // today's (pre-discount) output — no DISCOUNT line, nothing else changed.
  assertEqual(out, expected, 'cli prints the ORD-A invoice exactly (no discountCode: byte-identical)');

  let code = 0;
  try {
    execFileSync('node', [cli, path.join(__dirname, 'fixtures', 'no-such-order.json')], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
  } catch (e) {
    code = e.status;
  }
  assertEqual(code, 1, 'a missing order file exits 1');

  // Worked example 1 (SPEC-T3.md) — SAVE10.
  const save10Out = execFileSync('node', [cli, path.join(__dirname, 'fixtures', 'order-b.json')], { encoding: 'utf8' });
  const save10Expected = [
    'INVOICE ORD-B',
    'ITEM Books qty=1 billable_kg=2.00 tier=small amount=8.00',
    'ITEM Monitor qty=1 billable_kg=10.80 tier=medium amount=15.00',
    'SHIPPING zone=domestic amount=4.50',
    'SUBTOTAL 23.00',
    'DISCOUNT code=SAVE10 amount=2.30',
    'TAX 1.45',
    'TOTAL 26.65',
    '',
  ].join('\n');
  assertEqual(save10Out, save10Expected, 'cli prints the ORD-B (SAVE10) invoice exactly');

  // Worked example 2 (SPEC-T3.md) — FREESHIP.
  const freeshipOut = execFileSync('node', [cli, path.join(__dirname, 'fixtures', 'order-c.json')], { encoding: 'utf8' });
  const freeshipExpected = [
    'INVOICE ORD-C',
    'ITEM Desk qty=1 billable_kg=30.00 tier=large amount=41.00',
    'SHIPPING zone=international amount=0.00',
    'SUBTOTAL 41.00',
    'DISCOUNT code=FREESHIP amount=22.00',
    'TAX 2.87',
    'TOTAL 43.87',
    '',
  ].join('\n');
