6	const { applyDiscount } = require('./discount');
7	
8	// Tax is charged on the parcel subtotal only; shipping is never taxed.
9	const TAX_RATE = 0.07;
10	
11	// buildInvoice(order) -> {
12	//   id,
13	//   lines: [{ description, quantity, billableKg, tier, amountUsd }],
14	//   shippingZone, shippingUsd,
15	//   subtotalUsd, discount, taxUsd, totalUsd
16	// }
17	//
18	// `discount` is null when order.discountCode is absent, otherwise
19	// { code, amountUsd } for the applied discount (see lib/discount.js).
20	//
21	// order = {
22	//   id: string,
23	//   zone: 'domestic' | 'regional' | 'international',
24	//   items: [{ description, quantity?, weightKg, dimensionsCm: { length, width, height } }],
25	//   discountCode?: string
26	// }
27	function buildInvoice(order) {
28	  if (!order || typeof order !== 'object') {
29	    throw new TypeError('buildInvoice requires an order object');
30	  }
31	  if (typeof order.id !== 'string' || order.id === '') {
32	    throw new TypeError('order.id must be a non-empty string');
33	  }
34	  if (!Array.isArray(order.items) || order.items.length === 0) {
35	    throw new TypeError('order.items must be a non-empty array');
36	  }
37	
38	  const lines = [];
39	  let subtotal = 0;
40	  for (const item of order.items) {
41	    const quantity = item.quantity === undefined ? 1 : item.quantity;
42	    if (!Number.isInteger(quantity) || quantity <= 0) {
43	      throw new TypeError('item.quantity must be a positive integer');
44	    }
45	    const kg = billableWeightKg(item.weightKg, item.dimensionsCm);
46	    const amountUsd = roundCurrency(quantity * basePriceUsd(kg));
47	    lines.push({
48	      description: item.description,
49	      quantity,
50	      billableKg: kg,
51	      tier: tierFor(kg),
52	      amountUsd,
53	    });
54	    subtotal += amountUsd;
55	  }
56	
57	  const subtotalUsd = roundCurrency(subtotal);
58	  let shipUsd = shippingUsd(order.zone);
59	
60	  let discount = null;
61	  let taxUsd;
62	  let totalUsd;
63	
64	  if (order.discountCode !== undefined) {
65	    const result = applyDiscount(order.discountCode, {
66	      subtotalUsd,
67	      shippingUsd: shipUsd,
68	      taxRate: TAX_RATE,
69	    });
70	    discount = { code: result.code, amountUsd: result.amountUsd };
71	    shipUsd = result.shippingUsd;
72	    taxUsd = result.taxUsd;
73	    totalUsd = result.totalUsd;
74	  } else {
75	    taxUsd = roundCurrency(TAX_RATE * subtotalUsd);
76	    totalUsd = roundCurrency(subtotalUsd + shipUsd + taxUsd);
77	  }
78	
79	  return {
80	    id: order.id,
81	    lines,
82	    shippingZone: order.zone,
83	    shippingUsd: shipUsd,
84	    subtotalUsd,
85	    discount,
86	    taxUsd,
87	    totalUsd,
88	  };
89	}
90	
91	module.exports = { buildInvoice, TAX_RATE };
