  const cli = path.join(__dirname, '..', 'bin', 'cli.js');
  const fixture = (name) => path.join(__dirname, 'fixtures', name);

  // Worked example (FOLLOWUP-T5.md) — order-b.json (SAVE10) + order-c.json (FREESHIP).
  const worked = execFileSync(
    'node',
    [cli, '--summary', fixture('order-b.json'), fixture('order-c.json')],
    { encoding: 'utf8' }
  );
  const workedExpected = [
    'SUMMARY ORD-B total=26.65',
    'SUMMARY ORD-C total=43.87',
    'SUMMARY TOTAL orders=2 net=70.52',
    '',
  ].join('\n');
  assertEqual(worked, workedExpected, '--summary prints the worked-example two-order summary exactly');

  // Single order file: sanity check of orders=1 / net= with one file.
  const single = execFileSync('node', [cli, '--summary', fixture('order-a.json')], { encoding: 'utf8' });
