  let bogusStdout = '';
  let bogusStderr = '';
  let bogusCode = 0;
  try {
    bogusStdout = execFileSync('node', [cli, '--summary', fixture('order-bogus.json')], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
  } catch (e) {
    bogusCode = e.status;
    bogusStdout = e.stdout;
    bogusStderr = e.stderr;
