  // already have been printed (sequential processing), but no SUMMARY TOTAL line,
  // since the run fails before reaching the end of the loop.
  let multiStdout = '';
  let multiStderr = '';
  let multiCode = 0;
  try {
    multiStdout = execFileSync(
      'node',
      [cli, '--summary', fixture('order-b.json'), fixture('order-bogus.json')],
      { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }
    );
  } catch (e) {
    multiCode = e.status;
    multiStdout = e.stdout;
    multiStderr = e.stderr;
  }
  assertEqual(multiStdout, 'SUMMARY ORD-B total=26.65\n', '--summary prints earlier SUMMARY lines before a later failure, and nothing more');
  assertEqual(multiStderr, 'parcel-billing: unknown discount code: BOGUS\n', '--summary with a later unknown discount code prints the exact stderr message');
  assertEqual(multiCode, 2, '--summary with a later unknown discount code exits 2');

  // A missing/unreadable order file exits 1.
  let missingCode = 0;
  try {
    execFileSync('node', [cli, '--summary', fixture('no-such-order.json')], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    });
  } catch (e) {
    missingCode = e.status;
  }
  assertEqual(missingCode, 1, '--summary with a missing order file exits 1');
};

