'use strict';

// parcel-billing CLI: read a JSON order file, print an invoice.
//   node bin/cli.js <order.json>

const fs = require('fs');
const { buildInvoice } = require('../lib/invoice');
const { money, roundCurrency } = require('../lib/format');
const { UnknownDiscountCodeError } = require('../lib/discount');

function fail(message, code) {
  process.stderr.write('parcel-billing: ' + message + '\n');
  process.exit(code);
}

// --summary <order-file> [<order-file> ...]
//
// Builds each order's invoice (reusing buildInvoice — no discount/rounding
// logic is re-implemented here) and prints one SUMMARY line per order,
// in argument order, followed by a SUMMARY TOTAL line. Each per-order line
// is written to stdout as soon as that order is processed (not buffered),
// so that if a later file fails, earlier SUMMARY lines have already been
// printed. Failures mirror the normal invoice path exactly: unknown discount
// code -> same stderr message, exit 2; unreadable/invalid order -> exit 1.
function runSummary(files) {
  if (files.length === 0) {
    process.stderr.write('usage: node bin/cli.js --summary <order-file> [<order-file> ...]\n');
    process.exit(1);
  }

  let sum = 0;
  for (const file of files) {
    let order;
    try {
      order = JSON.parse(fs.readFileSync(file, 'utf8'));
    } catch (e) {
      fail('cannot read order file: ' + file, 1);
    }

    let invoice;
    try {
      invoice = buildInvoice(order);
    } catch (e) {
      if (e instanceof UnknownDiscountCodeError) {
        fail(e.message, 2);
      }
      fail('invalid order: ' + e.message, 1);
    }

    // Use a synchronous fd write (not process.stdout.write) so that this
    // line is guaranteed to be flushed before a later iteration's fail()
    // calls process.exit() — process.stdout can be an asynchronous pipe
    // when captured by a parent process.
    fs.writeSync(1, 'SUMMARY ' + invoice.id + ' total=' + money(invoice.totalUsd) + '\n');
    sum += invoice.totalUsd;
  }

  fs.writeSync(1, 'SUMMARY TOTAL orders=' + files.length + ' net=' + money(roundCurrency(sum)) + '\n');
}

function main(argv) {
  if (argv[0] === '--summary') {
    runSummary(argv.slice(1));
    return;
  }

  if (argv.length !== 1) {
    process.stderr.write('usage: node bin/cli.js <order.json>\n');
    process.exit(1);
  }
  const file = argv[0];

  let order;
  try {
    order = JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (e) {
    fail('cannot read order file: ' + file, 1);
  }

  let invoice;
  try {
    invoice = buildInvoice(order);
  } catch (e) {
    if (e instanceof UnknownDiscountCodeError) {
      fail(e.message, 2);
    }
    fail('invalid order: ' + e.message, 1);
  }

  const out = [];
  out.push('INVOICE ' + invoice.id);
  for (const line of invoice.lines) {
    out.push(
      'ITEM ' + line.description +
      ' qty=' + line.quantity +
      ' billable_kg=' + line.billableKg.toFixed(2) +
      ' tier=' + line.tier +
      ' amount=' + money(line.amountUsd)
    );
  }
  out.push('SHIPPING zone=' + invoice.shippingZone + ' amount=' + money(invoice.shippingUsd));
  out.push('SUBTOTAL ' + money(invoice.subtotalUsd));
  if (invoice.discount) {
    out.push('DISCOUNT code=' + invoice.discount.code + ' amount=' + money(invoice.discount.amountUsd));
  }
  out.push('TAX ' + money(invoice.taxUsd));
  out.push('TOTAL ' + money(invoice.totalUsd));
  process.stdout.write(out.join('\n') + '\n');
}

main(process.argv.slice(2));

