35	    throw new TypeError('order.items must be a non-empty array');
36	  }
37	
38	  const lines = [];
39	  let subtotal = 0;
40	  for (const item of order.items) {
41	    const quantity = item.quantity === undefined ? 1 : item.quantity;
42	    if (!Number.isInteger(quantity) || quantity <= 0) {
