3	// Discount codes: the code table and the amount-computation logic live here,
4	// and only here. lib/invoice.js and bin/cli.js consume this module; neither
5	// re-implements a discount rule or re-implements rounding. All rounding goes
6	// through lib/format.js's roundCurrency, per the project's rounding policy.
7	
8	const { roundCurrency } = require('./format');
9	
10	const CODES = new Set(['SAVE10', 'FREESHIP']);
11	
12	class UnknownDiscountCodeError extends Error {
13	  constructor(code) {
14	    super('unknown discount code: ' + code);
15	    this.name = 'UnknownDiscountCodeError';
16	    this.code = code;
17	  }
18	}
