20	// applyDiscount(code, { subtotalUsd, shippingUsd, taxRate }) -> {
21	//   code, amountUsd, shippingUsd, taxUsd, totalUsd
22	// }
23	//
24	// subtotalUsd and shippingUsd are the order's pre-discount subtotal and
25	// shipping charge; taxRate is the project's tax rate (see lib/invoice.js).
26	// Returns the discount amount shown on the invoice plus the (possibly
27	// adjusted) shipping/tax/total figures. Throws UnknownDiscountCodeError if
28	// `code` is not exactly one of the recognized codes.
29	function applyDiscount(code, { subtotalUsd, shippingUsd, taxRate }) {
30	  if (!CODES.has(code)) {
31	    throw new UnknownDiscountCodeError(code);
32	  }
33	
34	  if (code === 'SAVE10') {
35	    const amountUsd = Math.min(roundCurrency(0.1 * subtotalUsd), 50);
36	    const taxableUsd = roundCurrency(subtotalUsd - amountUsd);
37	    const taxUsd = roundCurrency(taxRate * taxableUsd);
38	    const totalUsd = roundCurrency(taxableUsd + shippingUsd + taxUsd);
39	    return { code, amountUsd, shippingUsd, taxUsd, totalUsd };
40	  }
41	
42	  // FREESHIP: shipping is zeroed; the discount amount shown is the zone's
43	  // normal shipping price. Subtotal and tax are unaffected.
44	  const amountUsd = shippingUsd;
45	  const taxUsd = roundCurrency(taxRate * subtotalUsd);
46	  const totalUsd = roundCurrency(subtotalUsd + taxUsd);
47	  return { code, amountUsd, shippingUsd: 0, taxUsd, totalUsd };
48	}
